import {SAVE_SLOTS,listSaves} from './save-store.js';
import {formatClock} from './game-clock.js';
const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;};
export function createSavePanel({onSave,onLoad,onOpen,onClose,slots=SAVE_SLOTS,list=listSaves,title:panelTitle="Save / Load"}){
 const dialog=el('dialog');dialog.id='save-screen';dialog.className='save-screen';dialog.setAttribute('aria-labelledby','save-title');document.body.append(dialog);let busy=false,generation=0;
 const title=el('h2',panelTitle);title.id='save-title';const close=el('button','Close');close.onclick=()=>dialog.close();const top=el('div');top.className='save-top';top.append(title,close);const hint=el('p','Saves are stored in this browser on this site. Loaded encounters start paused.');const rows=el('div'),status=el('p');status.setAttribute('role','status');dialog.append(top,hint,rows,status);
 async function render(){const revision=++generation;try{const records=await list();if(revision!==generation)return;rows.replaceChildren();for(const [id,label]of slots){const record=records.find(r=>r.id===id),row=el('section');row.className='save-row';const heading=el('strong',label),details=el('p',record?record.mapName+' · '+formatClock({minutes:record.minutes})+' · Round '+record.round+' · '+new Date(record.savedAt).toLocaleString():'Empty');row.append(heading,details);if(onSave&&!['auto','continue'].includes(id)){const save=el('button',record?'Overwrite':'Save');save.setAttribute('aria-label',(record?'Overwrite ':'Save to ')+label);save.onclick=()=>run(async()=>{await onSave(id);status.textContent=label+' saved.';await render();});row.append(save);}const load=el('button','Load');load.setAttribute('aria-label','Load '+label);load.disabled=!record;load.onclick=()=>run(async()=>{await onLoad(id);dialog.close();});row.append(load);rows.append(row);}}catch(e){status.textContent='Could not read saves: '+e.message;}}
 async function run(fn){if(busy)return;busy=true;close.disabled=true;for(const b of rows.querySelectorAll('button'))b.disabled=true;try{await fn();}catch(e){status.textContent=e.message;}finally{busy=false;close.disabled=false;if(dialog.open)await render();}}
 dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{generation++;onClose?.();});
 return {get open(){return dialog.open;},async show(){status.textContent='';dialog.showModal();onOpen?.();await render();close.focus();}};
}
